#include "rpg/pve_visual.hpp"
#include "rpg/arena_layout.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;using namespace rpg::presentation;
void check(bool ok,const char* why){if(!ok){throw std::runtime_error(why);}}
const Fighter& unit(const Snapshot& s,std::string_view id){const auto i=std::ranges::find(s.fighters,id,[](const Fighter& f){return f.definition.id;});if(i==s.fighters.end()){throw std::runtime_error("missing entity");}return *i;}
void step(SharedVisualSession& s){const auto v=s.state();if(v.automatic){check(s.step_automatic().accepted(),"boss automation");}else{const auto ids=s.targets(1);check(!ids.empty()&&s.submit(v.revision,1,ids[0]).accepted(),"player action");}}
void definition(){SharedVisualSession s;const auto o=s.observation();check(o.squad_ids.size()==3&&o.battle.fighters.size()==4&&s.hud().boss_max_health==150000,"one boss and three fronts");check(s.state().combat.profile==CombatProfile::Team&&s.hud().global_goal==200,"common profile and global budget");for(const auto& front:s.hud().fronts){check(front.members.size()==1&&front.active&&front.allied_actions==0,"initial fronts");}}
void purity(){SharedVisualSession s;const auto before=s.observation();for(int i=0;i<50;++i){static_cast<void>(s.state());static_cast<void>(s.hud());static_cast<void>(s.targets(1));}check(s.observation()==before&&s.hud().global_actions==0,"no side effects by read");}
void shared_hp(){SharedVisualSession s;const auto hp=s.hud().boss_health;check(s.submit(0,1,"CHEFE-PAR").accepted(),"first hit");const auto o=s.observation();check(s.hud().boss_health<hp&&unit(o.battle,"CHEFE-PAR").health==s.hud().boss_health,"single HP source");check(std::ranges::count_if(o.battle.fighters,[](const Fighter& f){return f.definition.id=="CHEFE-PAR";})==1,"boss never cloned");check(s.hud().fronts[0].allied_actions==1,"actor-front counter");}
void rotation(){auto d=shared_lab_definition();d.encounter.boss.speed=200;d.encounter.boss.max_health=1000000;SharedVisualSession s(d);std::vector<std::string> fronts;for(int i=0;i<60&&fronts.size()<3;++i){const auto before=s.hud().boss_actions;step(s);if(s.hud().boss_actions!=before){fronts.push_back(*s.hud().last_local_front);}}check(fronts==std::vector<std::string>{"frente-1","frente-2","frente-3"},"core rotation across live fronts");}
void global(){auto d=shared_lab_definition(true);d.encounter.boss.speed=200;for(auto& squad:d.encounter.squads){squad.members[0].fighter.stats.block=0;}SharedVisualSession s(d);const auto before=s.observation();check(s.step_automatic().accepted(),"global special");const auto after=s.observation();for(const auto& front:before.members){for(const auto& id:front){check(unit(after.battle,id).health<unit(before.battle,id).health,"global reaches all fronts");}}check(s.hud().boss_actions==1&&s.hud().global_actions==1&&s.hud().next_local_front=="frente-1"&&!s.hud().last_local_front,"global is one action and does not rotate local cursor");}
void dead_front(){auto d=shared_lab_definition();d.encounter.boss.speed=200;d.encounter.squads[0].members[0].fighter.max_health=1;d.encounter.squads[0].members[0].fighter.stats.block=0;SharedVisualSession s(d);check(s.step_automatic().accepted()&&!s.hud().fronts[0].active&&s.hud().next_local_front=="frente-2"&&!s.finished(),"dead front skipped without ending other fronts");}
void own_scope(){auto d=shared_lab_definition();for(auto& f:d.encounter.squads){f.members[0].fighter.speed=1;}d.encounter.squads[1].members[0].fighter.speed=500;const auto skill=std::ranges::find(d.encounter.rules.skills,std::string("A1-terceira"),&SkillDefinition::id);skill->target=TargetRule::Ally;const auto scope=std::ranges::find(d.encounter.skill_scopes,skill->id,&SharedSkillScope::skill_id);scope->target=SharedSkillTarget::OwnSquad;SharedVisualSession s(d);check(s.targets(3)==std::vector<std::string>{"A1"},"UI filters other fronts");const auto before=s.observation();auto wrong=s.submit(0,3,"FELIPE");check(!wrong.accepted()&&wrong.action.error==ActionError::InvalidSkillTarget&&s.observation()==before,"cross-front attempt rejected atomically");check(s.submit(0,3,"A1").accepted(),"own front allowed");}
void stale_scope(){SharedVisualSession s;const auto before=s.observation();check(!s.submit(0,1,"FELIPE").accepted()&&s.observation()==before,"enemy attack cannot hit ally");check(!s.submit_action(0,{"FELIPE",ActionType::Skill,"CHEFE-PAR","FELIPE-A1",{"CHEFE-PAR"}}).accepted()&&s.observation()==before,"UI cannot inject target scope");check(s.submit(0,1,"CHEFE-PAR").accepted()&&s.submit(0,1,"CHEFE-PAR").error==VisualError::StaleCommand,"revision safety");}
void end_limit(){auto d=shared_lab_definition();d.encounter.boss.max_health=1;d.encounter.boss.stats.block=0;SharedVisualSession win(d);check(win.submit(0,1,"CHEFE-PAR").accepted()&&win.finished()&&win.hud().objective_met&&!win.hud().next_local_front,"boss defeat ends all fronts");d=shared_lab_definition();d.encounter.rules.action_budget=ActionBudget{1,LimitOutcome::Draw};SharedVisualSession limited(d);check(limited.submit(0,1,"CHEFE-PAR").accepted()&&limited.finished()&&!limited.hud().objective_met&&limited.hud().global_remaining==0,"limit not victory");}
void reset(){SharedVisualSession s;check(s.submit(0,1,"CHEFE-PAR").accepted(),"partial shared");s.abandon();const auto before=s.observation();check(s.submit(s.state().revision,1,"CHEFE-PAR").error==VisualError::SafetyStop&&s.observation()==before,"abandon inert");s.reset();check(s.hud().global_actions==0&&s.hud().boss_actions==0&&s.hud().boss_health==150000&&s.hud().next_local_front=="frente-1"&&s.state().progress.attempt==2,"fresh shared encounter");}
void full_and_counts(){for(const bool global:{false,true}){SharedVisualSession s(shared_lab_definition(global));for(int i=0;i<220&&!s.finished();++i){step(s);}check(s.finished()&&s.hud().objective_met,"full shared battle");auto sum=s.hud().boss_actions;for(const auto& front:s.hud().fronts){sum+=front.allied_actions;}check(sum==s.hud().global_actions&&s.state().progress.credits==0,"front counts not duplicated and no generic rewards");}}
void layout(){SharedVisualSession s;auto o=s.observation();const auto p=shared_arena_placements(o);check(p.size()==4&&p[0].x<p[1].x&&p[1].x<p[2].x&&p[3].fighter_id=="CHEFE-PAR","three spatial fronts and one boss");o.members[0][0]="missing";bool caught=false;try{static_cast<void>(shared_arena_placements(o));}catch(const std::invalid_argument&){caught=true;}check(caught,"invalid layout rejected");}
void fifteen(){auto d=shared_lab_definition();for(std::size_t i=0;i<3;++i){for(int j=1;j<5;++j){Definition f{"EX-"+std::to_string(i)+"-"+std::to_string(j),Team::A,1000,10,50};const auto skill=f.id+"-A1";SkillDefinition attack{skill,f.id,0,TargetRule::Enemy,{{EffectKind::Damage}}};attack.basic=true;d.encounter.squads[i].members.push_back({f.id,f});d.encounter.rules.skills.push_back(attack);d.encounter.skill_scopes.push_back({skill,SharedSkillTarget::Boss});d.loadouts.push_back({f.id,{{1,"Attack",skill,""}}});}}SharedVisualSession s(d);check(shared_arena_placements(s.observation()).size()==16,"geometry supports three times five plus boss");}
void isolation(){VisualSession generic(terminal_lab_setup());PveVisualSession ritual;SequentialVisualSession sequence;const auto a=generic.state();const auto b=ritual.observation();const auto c=sequence.observation();SharedVisualSession shared;check(shared.submit(0,1,"CHEFE-PAR").accepted(),"shared independent action");check(generic.state().combat==a.combat&&ritual.observation()==b&&sequence.observation()==c,"other modes unaffected");}
int main(){try{definition();purity();shared_hp();rotation();global();dead_front();own_scope();stale_scope();end_limit();reset();full_and_counts();layout();fifteen();isolation();std::cout<<"REG_SHARED_VISUAL_TESTS_RESULT passed=14 total=14\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}